package pe.com.asistencia.request.domain;
import jakarta.persistence.*; import pe.com.asistencia.employee.domain.Employee; import pe.com.asistencia.security.domain.User; import pe.com.asistencia.attendance.domain.*; import java.time.*;
@Entity @Table(name="employee_requests")
public class EmployeeRequest {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="employee_id") private Employee employee; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="attendance_day_id") private AttendanceDay attendanceDay; @Enumerated(EnumType.STRING) @Column(name="request_type",nullable=false) private RequestType type; @Column(name="affected_date") private LocalDate affectedDate; @Column(nullable=false,length=1000) private String reason; @Column(name="requested_from") private Instant requestedFrom; @Column(name="requested_to") private Instant requestedTo; @Enumerated(EnumType.STRING) @Column(name="proposed_punch_type") private PunchType proposedPunchType; @Column(name="proposed_at") private Instant proposedAt; @Column(name="requested_change",length=1000) private String requestedChange; @Column(name="evidence_reference",length=500) private String evidenceReference; @Enumerated(EnumType.STRING) @Column(nullable=false) private RequestStatus status=RequestStatus.SUBMITTED; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="reviewed_by") private User reviewedBy; @Column(name="review_comment",length=1000) private String reviewComment; @Column(name="submitted_at",insertable=false,updatable=false) private Instant submittedAt; @Column(name="resolved_at") private Instant resolvedAt;
 protected EmployeeRequest(){} public EmployeeRequest(Employee e,RequestType type,String reason,Instant from,Instant to,String change,String evidence){employee=e;this.type=type;this.reason=reason;requestedFrom=from;requestedTo=to;requestedChange=change;evidenceReference=evidence;}
 public EmployeeRequest(Employee e,AttendanceDay day,RequestType type,LocalDate affectedDate,String reason,Instant from,Instant to,PunchType proposedPunchType,Instant proposedAt,String change,String evidence){employee=e;attendanceDay=day;this.type=type;this.affectedDate=affectedDate;this.reason=reason;requestedFrom=from;requestedTo=to;this.proposedPunchType=proposedPunchType;this.proposedAt=proposedAt;requestedChange=change;evidenceReference=evidence;}
 public void review(User reviewer,RequestStatus decision,String comment){if(status==RequestStatus.APPROVED||status==RequestStatus.REJECTED)throw new IllegalStateException("La solicitud ya fue resuelta");if(decision!=RequestStatus.APPROVED&&decision!=RequestStatus.REJECTED)throw new IllegalArgumentException("Decisión inválida");reviewedBy=reviewer;status=decision;reviewComment=comment;resolvedAt=Instant.now();}
 public Long getId(){return id;} public Employee getEmployee(){return employee;} public AttendanceDay getAttendanceDay(){return attendanceDay;} public RequestType getType(){return type;} public LocalDate getAffectedDate(){return affectedDate;} public String getReason(){return reason;} public Instant getRequestedFrom(){return requestedFrom;} public Instant getRequestedTo(){return requestedTo;} public PunchType getProposedPunchType(){return proposedPunchType;} public Instant getProposedAt(){return proposedAt;} public String getRequestedChange(){return requestedChange;} public String getEvidenceReference(){return evidenceReference;} public RequestStatus getStatus(){return status;} public User getReviewedBy(){return reviewedBy;} public String getReviewComment(){return reviewComment;} public Instant getSubmittedAt(){return submittedAt;} public Instant getResolvedAt(){return resolvedAt;}
}
